#!/bin/sh
# DOWNLOAD-ONLY: the caller must first verify this exact artifact SHA-256 and
# set the explicit guard.  This script writes source bytes only; it never
# invokes Node, reads a token, makes a network request, or sends a message.
(
set -eu
umask 077
PATH=/usr/bin:/bin
export PATH
LC_ALL=C
export LC_ALL
exec 2>/dev/null

stage_result_emitted=0
stage_failure() {
  if [ "$stage_result_emitted" -eq 0 ]; then
    stage_result_emitted=1
    printf '%s\n' '{"ok":false,"operation":"aru_discord_visible_canary_stage","error_code":"ARU_DISCORD_VISIBLE_CANARY_STAGE_REJECTED","sensitive_output_count":0}'
  fi
  trap - 0
  exit 2
}
trap 'if [ "$stage_result_emitted" -eq 0 ]; then stage_result_emitted=1; printf "%s\n" "{\"ok\":false,\"operation\":\"aru_discord_visible_canary_stage\",\"error_code\":\"ARU_DISCORD_VISIBLE_CANARY_STAGE_REJECTED\",\"sensitive_output_count\":0}"; fi' 0

assert_private_directory() {
  [ ! -L "$1" ] || stage_failure
  [ -d "$1" ] || stage_failure
  [ "$(/usr/bin/stat -c '%F:%u:%a' -- "$1")" = 'directory:0:700' ] || stage_failure
}
create_fresh_private_directory() {
  [ ! -L "$1" ] || stage_failure
  [ ! -e "$1" ] || stage_failure
  /usr/bin/mkdir -m 700 -- "$1" || stage_failure
  assert_private_directory "$1"
}
assert_private_regular_file() {
  [ ! -L "$1" ] || stage_failure
  [ "$(/usr/bin/stat -c '%F:%u:%a:%s' -- "$1")" = "regular file:0:400:$3" ] || stage_failure
  [ "$(/usr/bin/stat -c '%h' -- "$1")" = 1 ] || stage_failure
  actual_hash=$(/usr/bin/sha256sum -- "$1" | /usr/bin/cut -d ' ' -f 1) || stage_failure
  [ "$actual_hash" = "$2" ] || stage_failure
}
assert_nonwritable_anchor_directory() {
  [ ! -L "$1" ] || stage_failure
  [ -d "$1" ] || stage_failure
  anchor=$(/usr/bin/stat -c '%F:%u:%a' -- "$1") || stage_failure
  case "$anchor" in directory:0:7[0145][0145]) ;; *) stage_failure ;; esac
}

[ "$#" -eq 0 ] || stage_failure
[ "${HERMES_ARU_VISIBLE_CANARY_STAGE:-}" = 1 ] || stage_failure
[ "$(/usr/bin/id -u)" = 0 ] || stage_failure
assert_nonwritable_anchor_directory /
assert_nonwritable_anchor_directory /root

